import React from 'react';
import {
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  Typography,
} from '@mui/material';
import { EmojiEvents as TrophyIcon } from '@mui/icons-material';
import { keyframes } from '@mui/system';

const celebratePulse = keyframes`
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.12); }
`;

const confettiFall = keyframes`
  0% { transform: translateY(-12px) rotate(0deg); opacity: 1; }
  100% { transform: translateY(72px) rotate(360deg); opacity: 0; }
`;

const CONFETTI_COLORS = ['#4caf50', '#2196f3', '#ff9800', '#9c27b0', '#00bcd4'];

export interface AchievementCelebrationTarget {
  id: string;
  title: string;
  description: string;
  points: number;
}

interface AchievementCelebrationDialogProps {
  achievement: AchievementCelebrationTarget | null;
  open: boolean;
  onClose: () => void;
  reducedMotion?: boolean;
  headline?: string;
  showPoints?: boolean;
}

export const AchievementCelebrationDialog: React.FC<AchievementCelebrationDialogProps> = ({
  achievement,
  open,
  onClose,
  reducedMotion = false,
  headline = 'Achievement unlocked!',
  showPoints = true,
}) => {
  if (!achievement) return null;

  return (
    <Dialog
      open={open}
      onClose={onClose}
      maxWidth="xs"
      fullWidth
      aria-labelledby="achievement-celebration-title"
    >
      <DialogContent sx={{ textAlign: 'center', pt: 4, pb: 2, position: 'relative', overflow: 'hidden' }}>
        {!reducedMotion
          ? CONFETTI_COLORS.map((color, index) => (
              <Box
                key={`${achievement.id}-confetti-${index}`}
                aria-hidden
                sx={{
                  position: 'absolute',
                  top: 12 + (index % 3) * 8,
                  left: `${12 + index * 16}%`,
                  width: 8,
                  height: 8,
                  borderRadius: '50%',
                  bgcolor: color,
                  animation: `${confettiFall} 1.4s ease-out ${index * 0.08}s`,
                }}
              />
            ))
          : null}
        <TrophyIcon
          color="warning"
          sx={{
            fontSize: 64,
            mb: 1.5,
            animation: reducedMotion ? undefined : `${celebratePulse} 0.9s ease-in-out 2`,
          }}
        />
        <Typography id="achievement-celebration-title" variant="h5" sx={{ fontWeight: 800, mb: 1 }}>
          {headline}
        </Typography>
        <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: 0.5 }}>
          {achievement.title}
        </Typography>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 1.5 }}>
          {achievement.description}
        </Typography>
        {showPoints && achievement.points > 0 ? (
          <Typography variant="body2" color="primary" sx={{ fontWeight: 700 }}>
            +{achievement.points} points
          </Typography>
        ) : null}
      </DialogContent>
      <DialogActions sx={{ justifyContent: 'center', pb: 3 }}>
        <Button variant="contained" onClick={onClose}>
          Continue
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default AchievementCelebrationDialog;
