/** Application lifecycle stages for loans and GIFT schemes. */

export type TimelineStepState = 'complete' | 'active' | 'upcoming' | 'error';

export interface TimelineStep {
  key: string;
  label: string;
  description: string;
  state: TimelineStepState;
}

const LOAN_TIMELINE = [
  { key: 'submitted', label: 'Submitted', description: 'Application received by the platform.' },
  { key: 'under_review', label: 'Under review', description: 'Lender is reviewing your documents and carbon profile.' },
  { key: 'approved', label: 'Approved', description: 'Loan approved — disbursement steps follow.' },
  { key: 'disbursed', label: 'Disbursed', description: 'Funds released to your account.' },
  { key: 'rejected', label: 'Rejected', description: 'Application was not approved.' },
];

const GIFT_TIMELINE = [
  { key: 'draft', label: 'Draft', description: 'Application saved but not yet submitted.' },
  { key: 'submitted', label: 'Submitted', description: 'Application sent for review.' },
  { key: 'under_review', label: 'Under review', description: 'Scheme administrator is evaluating eligibility.' },
  { key: 'approved', label: 'Approved', description: 'Application approved — benefit processing begins.' },
  { key: 'disbursed', label: 'Disbursed', description: 'Incentive or grant disbursed.' },
  { key: 'completed', label: 'Completed', description: 'Application lifecycle complete.' },
  { key: 'rejected', label: 'Rejected', description: 'Application was not approved.' },
  { key: 'cancelled', label: 'Cancelled', description: 'Application was withdrawn or cancelled.' },
];

const buildTimelineSteps = (
  timeline: { key: string; label: string; description: string }[],
  currentStatus: string
): TimelineStep[] => {
  const currentIdx = timeline.findIndex((s) => s.key === currentStatus);
  const idx = currentIdx >= 0 ? currentIdx : 0;
  const isTerminal = currentStatus === 'rejected' || currentStatus === 'cancelled';
  return timeline
    .filter((step) => !isTerminal || step.key === currentStatus || timeline.indexOf(step) <= idx)
    .map((step) => {
      const stepIdx = timeline.indexOf(step);
      let state: TimelineStepState = 'upcoming';
      if (isTerminal && step.key === currentStatus) {
        state = 'error';
      } else if (stepIdx < idx) {
        state = 'complete';
      } else if (stepIdx === idx) {
        state = 'active';
      }
      return { ...step, state };
    });
};

export const buildLoanTimeline = (status: string): TimelineStep[] =>
  buildTimelineSteps(LOAN_TIMELINE, status);

export const buildGiftTimeline = (status: string): TimelineStep[] =>
  buildTimelineSteps(GIFT_TIMELINE, status);

export const LOAN_SLA_DAYS = 14;
export const GIFT_SLA_DAYS = 21;

export const estimateDecisionDate = (
  submittedAt: string | Date | undefined,
  slaDays: number
): Date | null => {
  if (!submittedAt) return null;
  const base = new Date(submittedAt);
  if (Number.isNaN(base.getTime())) return null;
  const eta = new Date(base);
  eta.setDate(eta.getDate() + slaDays);
  return eta;
};
